  "graphs": [
    {
      "graphId": "graph_1001",
      "referenceId": "acct_1001",
      "records": [
        {
          "attributes": { "type": "Account", "referenceId": "acct_1001" },
          "Customer_Number__c": "C-1001",
          "Name": "Alder Creek Cafe"
        },
        {
